parameters.jsCode:
const init = $('Initialize Parameters').first().json;
const classified = $json.message?.content ? JSON.parse($json.message.content) : {};

const projectName = (init.projectName && init.projectName.trim()) ? init.projectName.trim() : (classified.proposedProjectName || 'architecture-project');
const startAt = (init.startAt && init.startAt.trim()) ? init.startAt.trim() : (classified.startAt || 'business_analyst');

const slugify = (s) => String(s || '')
  .toLowerCase()
  .trim()
  .replace(/[^a-z0-9]+/g, '-')
  .replace(/^-+|-+$/g, '')
  .replace(/--+/g, '-');

const projectSlug = slugify(projectName) || 'architecture-project';

// Non-crypto stable hash (FNV-1a 32-bit)
const fnv1a = (str) => {
  let hash = 0x811c9dc5;
  for (let i = 0; i < str.length; i++) {
    hash ^= str.charCodeAt(i);
    hash = (hash * 0x01000193) >>> 0;
  }
  return ('0000000' + hash.toString(16)).slice(-8);
};

const requestHash = fnv1a(String(init.text || ''));

return [{
  json: {
    ...init,
    intent: classified.intent || 'create_project',
    confidence: classified.confidence ?? null,
    notes: classified.notes || null,
    projectName,
    projectSlug,
    startAt,
    runConfig: $('Run Config').first().json,
    requestHash,
  }
}];

